66	            logger.info("Notification of affinity rule, change type is: " + event.getChangeType() + ", raw rule is:\n "
67	                    + event.getContent());
68	        }
69	
70	        if (event.getChangeType().equals(ConfigChangeType.DELETED)) {
71	            affinityRouterRule = null;
72	            affinityRouter = null;
73	        } else {
74	            try {
75	                affinityRouterRule = AffinityRuleParser.parse(event.getContent());
76	                generateConditions(affinityRouterRule);
