32	/**
33	 * Application level router, "application.condition-router"
34	 */
35	public class ProviderAppStateRouter<T> extends ListenableStateRouter<T> {
36	    private static final ErrorTypeAwareLogger logger =
37	            LoggerFactory.getErrorTypeAwareLogger(ListenableStateRouter.class);
38	    public static final String NAME = "PROVIDER_APP_ROUTER";
39	    private String application;
40	    private final String currentApplication;
41	
42	    public ProviderAppStateRouter(URL url) {
43	        super(url, url.getApplication());
44	        this.currentApplication = url.getApplication();
45	    }
46	
47	    @Override
48	    public void notify(BitList<Invoker<T>> invokers) {
49	        if (CollectionUtils.isEmpty(invokers)) {
50	            return;
51	        }
52	
53	        Invoker<T> invoker = invokers.get(0);
54	        URL url = invoker.getUrl();
55	        String providerApplication = url.getRemoteApplication();
56	
57	        // provider application is empty or equals with the current application
58	        if (isEmpty(providerApplication)) {
59	            logger.warn(
60	                    CLUSTER_TAG_ROUTE_EMPTY,
61	                    "condition router get providerApplication is empty, will not subscribe to provider app rules.",
62	                    "",
63	                    "");
64	            return;
65	        }
66	        if (providerApplication.equals(currentApplication)) {
67	            return;
68	        }
69	
70	        synchronized (this) {
71	            if (!providerApplication.equals(application)) {
72	                if (StringUtils.isNotEmpty(application)) {
73	                    this.getRuleRepository().removeListener(application + RULE_SUFFIX, this);
74	                }
75	                String key = providerApplication + RULE_SUFFIX;
76	                this.getRuleRepository().addListener(key, this);
77	                application = providerApplication;
78	                String rawRule = this.getRuleRepository().getRule(key, DynamicConfiguration.DEFAULT_GROUP);
79	                if (StringUtils.isNotEmpty(rawRule)) {
80	                    this.process(new ConfigChangedEvent(key, DynamicConfiguration.DEFAULT_GROUP, rawRule));
81	                }
82	            }
83	        }
84	    }
85	}
