940	    public static String camelToSplitName(String camelName, String split) {
941	        if (isEmpty(camelName)) {
942	            return camelName;
943	        }
944	        if (!isWord(camelName)) {
945	            // convert Ab-Cd-Ef to ab-cd-ef
946	            if (isSplitCase(camelName, split.charAt(0))) {
947	                return camelName.toLowerCase();
948	            }
949	            // not camel case
950	            return camelName;
951	        }
952	
953	        StringBuilder buf = null;
954	        for (int i = 0; i < camelName.length(); i++) {
955	            char ch = camelName.charAt(i);
956	            if (ch >= 'A' && ch <= 'Z') {
957	                if (buf == null) {
958	                    buf = new StringBuilder();
959	                    if (i > 0) {
960	                        buf.append(camelName, 0, i);
961	                    }
962	                }
963	                if (i > 0) {
964	                    buf.append(split);
965	                }
966	                buf.append(Character.toLowerCase(ch));
967	            } else if (buf != null) {
968	                buf.append(ch);
969	            }
970	        }
971	        return buf == null ? camelName.toLowerCase() : buf.toString().toLowerCase();
972	    }
