974	    private static boolean isSplitCase(String str, char separator) {
975	        if (str == null) {
976	            return false;
977	        }
978	        return str.chars().allMatch(ch -> (ch == separator) || isWord((char) ch));
979	    }
980	
981	    private static boolean isWord(String str) {
982	        if (str == null) {
983	            return false;
984	        }
985	        return str.chars().allMatch(ch -> isWord((char) ch));
986	    }
987	
988	    private static boolean isWord(char ch) {
989	        if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9')) {
990	            return true;
991	        }
992	        return false;
993	    }
